<?php /** The bills and the check, provider by provider. Data: s, check, may, here */ $id = (int) $s['ai_statement_id']; ?>
<div class="card mb-3" id="ai-bills"><div class="card-header"><h5 class="card-title mb-0">The bills and the check</h5>
    <?php if ($s['status'] === 'agrees' || $s['status'] === 'differs'): ?><span class="badge bg-<?= AI_STATUS_BADGE[$s['status']] ?>" id="ai-bills-verdict"><?= e($s['status']) ?></span><?php endif; ?></div>
    <?php if ($check === []): ?><div class="card-body text-muted" id="ai-bills-empty"><?= $s['kernel_status'] === 'closed' ? 'Not imported yet: Import makes one draft bill per provider.' : 'The month is still open in the OS; only a closed month becomes bills.' ?></div><?php else: ?>
    <div class="table-responsive"><table class="table table-sm mb-0" id="ai-bills-table"><thead><tr><th>Provider</th><th>Bill</th><th>Status</th><th class="text-end">Bill</th><th class="text-end">Statement</th><th class="text-end">Difference</th></tr></thead><tbody>
        <?php foreach ($check as $c): $rid = preg_replace('/[^a-z0-9]/i', '', $c['provider']) . '-' . $c['currency']; ?><tr id="ai-check-<?= e($rid) ?>" class="<?= $c['agrees'] ? '' : 'table-danger' ?>">
            <td><?= e(ai_provider_label($c['provider'])) ?></td><td><?= $c['bill_id'] !== null ? hx_link(with_back('/bills/' . $c['bill_id'], $here), e((string) $c['bill_number'])) : '—' ?></td><td><?= $c['bill_status'] !== null ? '<span class="badge bg-' . BILL_STATUS_BADGE[$c['bill_status']] . '">' . e(BILL_STATUSES[$c['bill_status']] ?? $c['bill_status']) . '</span>' : '' ?></td>
            <?= fmt_money_cell($c['bills_amount'], $c['currency']) ?><?= fmt_money_cell($c['statement_amount'], $c['currency']) ?><td class="text-end text-nowrap <?= $c['agrees'] ? 'text-success' : 'text-danger fw-semibold' ?>"><?= $c['agrees'] ? '✓ agrees' : e(fmt_money($c['difference'], $c['currency'], false)) ?></td></tr><?php endforeach; ?>
    </tbody></table></div>
    <?php $diffs = array_filter($check, static fn (array $c): bool => !$c['agrees']); if ($diffs !== []): ?><div class="card-body border-top fs-12" id="ai-bills-sentences"><?php foreach ($diffs as $c): ?><div class="mb-1"><?= e(ai_difference_sentence($c, $s['period'])) ?><?php if ($c['bill_status'] === 'void' && $may['write']): ?> <?= hx_link(with_back('/bills/new?copy_of=' . (int) $c['bill_id'], $here), 'Enter it from the voided bill', 'fw-semibold', 'id="ai-check-' . e(preg_replace('/[^a-z0-9]/i', '', $c['provider'])) . '-copy-link"') ?><?php endif; ?></div><?php endforeach; ?></div><?php endif; ?>
    <?php endif; ?>
</div>
